def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    centers = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] not in (0, 3)]
    blank_cross_cols = {c for r in range(1,h-1) for c in range(1,w-1) if grid[r][c] == 0 and all(grid[r+dr][c+dc] == 3 for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)))}
    original = {(r,c) for r in range(h) for c in range(w) if grid[r][c] != 0}
    for vertical in (False, True):
      for r,c,color in centers:
        own_arms = {(r+dr,c+dc) for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)) if 0<=r+dr<h and 0<=c+dc<w}
        for direction in (-1,1):
            y,x = (r,c+direction) if not vertical else (r+direction,c)
            while (0<=x<w) if not vertical else (0<=y<h):
                if grid[y][x] != 0 and (y,x) not in own_arms: break
                if (not vertical and x in blank_cross_cols): pass
                elif (y,x) not in original: out[y][x]=color
                if vertical: y += direction
                else: x += direction
    return out

